import {icons} from '/ui-icons.js';
import {themes} from './app-style-presets.mjs';
if(!document.getElementById('app-settings-toggle')){
const root=document.documentElement,KEY='sandbox-app-style-v1',LIKES='sandbox-style-favorites';let current=7,likes=[],category='All',timer,page=0;const PAGE=6;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(Number.isInteger(saved)&&saved>=0&&saved<themes.length)current=saved;const savedLikes=JSON.parse(localStorage.getItem(LIKES)||'[]');if(Array.isArray(savedLikes))likes=savedLikes.filter(i=>Number.isInteger(i)&&i>=0&&i<themes.length);}catch{}
function sheet(href,id){if(id&&document.getElementById(id))return;const l=document.createElement('link');l.rel='stylesheet';l.href=href;if(id)l.id=id;document.head.append(l);return l;}
if(!document.querySelector('link[href^="/app-style.css"]'))sheet('/app-style.css?v=sunroom-1');sheet('/app-appearance.css','app-appearance-css');
const fonts=sheet('', 'app-appearance-fonts'),toggle=document.createElement('button');toggle.id='app-settings-toggle';toggle.type='button';toggle.innerHTML=icons.settings;toggle.title='Settings';toggle.setAttribute('aria-label','Settings');toggle.setAttribute('aria-haspopup','dialog');toggle.setAttribute('aria-expanded','false');
const dialog=document.createElement('dialog');dialog.id='app-settings';dialog.setAttribute('aria-label','Settings');
// Settings is a panel with sections on the left; Style is one section, shown a page of previews at a time.
dialog.innerHTML=`<div class="settings-shell"><nav class="settings-nav" aria-label="Settings sections"><strong class="settings-title">Settings</strong><button type="button" data-settings-page="style" aria-current="page">Style</button><button type="button" data-settings-page="studies" aria-current="false">Studies</button><button type="button" id="appearance-close" aria-label="Close settings">${icons.close}</button></nav>
<section class="settings-page" data-settings-page="style" aria-label="Style"><div class="appearance-bar"><div class="appearance-heading"><small>STYLE</small><strong id="appearance-current"></strong></div><button type="button" id="appearance-prev" aria-label="Previous style">${icons.left}</button><button type="button" id="appearance-next" aria-label="Next style">${icons.right}</button></div><nav id="appearance-filters" aria-label="Style categories"></nav><div id="appearance-grid" aria-label="Styles"></div><div class="appearance-pager"><button type="button" id="appearance-page-prev" aria-label="Previous page">${icons.left}</button><span id="appearance-dots" role="tablist" aria-label="Style pages"></span><button type="button" id="appearance-page-next" aria-label="Next page">${icons.right}</button></div><div class="appearance-footer"><button type="button" id="appearance-like">♡ Like · Space</button><button type="button" id="appearance-reset">Reset to Sunroom</button><small id="appearance-fonts"></small><small id="appearance-storage">Saved on this device</small></div></section>
<section class="settings-page" data-settings-page="studies" aria-label="Studies" hidden><p class="settings-lede">Model and character studies behind the world.</p><a class="settings-card" href="/studies/"><strong>Studies</strong><span>Roman paper warrior rounds 1, 2 and 3, the props and kit, the helmet studies and the Atelier pack.</span></a><a class="settings-card" href="/models"><strong>Models</strong><span>Every finished model, with its reference image and a 3D view you can turn and zoom.</span></a></section></div>`;
const toast=document.createElement('div');toast.id='appearance-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.append(toggle,dialog);dialog.append(toast);
const $=id=>dialog.querySelector('#'+id);const categories=['All','Original','Studio','Silly','Kids','Liked'];
function visible(){return themes.map((_,i)=>i).filter(i=>category==='All'||category==='Liked'&&likes.includes(i)||(themes[i][15]||'Original')===category);}
function notice(message){clearTimeout(timer);toast.textContent=message;toast.hidden=false;timer=setTimeout(()=>toast.hidden=true,2200);}
function render(){const ids=visible(),pages=Math.max(1,Math.ceil(ids.length/PAGE));page=Math.min(Math.max(0,page),pages-1);$('appearance-grid').innerHTML=ids.slice(page*PAGE,page*PAGE+PAGE).map(i=>{const t=themes[i];return `<button type="button" data-style="${i}" aria-pressed="${i===current}" aria-label="${t[0]}"><span class="appearance-preview" style="background:${t[4]};color:${t[6]};font-family:&#39;${t[2]}&#39;,serif"><span style="background:${t[5]}">Aa<span class="appearance-preview-rule" style="background:${t[9]}"></span></span></span><span class="appearance-swatches">${[4,5,9,11].map(k=>`<i style="background:${t[k]}"></i>`).join('')}</span><span>${String(i+1).padStart(2,'0')} ${t[0]}</span></button>`;}).join('')||'<p>No liked styles yet.</p>';$('appearance-dots').innerHTML=Array.from({length:pages},(_,n)=>`<button type="button" role="tab" data-page="${n}" aria-selected="${n===page}" aria-label="Page ${n+1} of ${pages}"></button>`).join('');$('appearance-page-prev').disabled=page===0;$('appearance-page-next').disabled=page>=pages-1;for(const b of dialog.querySelectorAll('[data-category]'))b.setAttribute('aria-pressed',String(b.dataset.category===category));$('appearance-current').textContent=themes[current][0];$('appearance-like').textContent=(likes.includes(current)?'♥ Liked':'♡ Like')+' · Space';$('appearance-like').setAttribute('aria-pressed',String(likes.includes(current)));$('appearance-fonts').textContent=themes[current][2]+' / '+themes[current][3];}
function apply(i,persist=true){current=i;const t=themes[i],vars={'app-canvas':t[4],'app-paper':t[5],'app-ink':t[6],'app-muted':t[7],'app-border':t[8],'app-accent':t[9],'app-focus':t[9],'app-on-accent':t[10],'app-radius':t[14],'app-font':`'${t[3]}',sans-serif`,'app-heading':`'${t[2]}',serif`,'b3-panel':t[5],'b3-text':t[6],'b3-quiet':t[7],'b3-gold':t[9]};for(const [key,value]of Object.entries(vars))root.style.setProperty('--'+key,value);for(const key of ['b3-panel','b3-text','b3-quiet','b3-gold'])document.body.style.setProperty('--'+key,vars[key]);root.dataset.appStyle=String(i+1);root.dataset.appStyleName=t[0];const families=[...new Set([t[2],t[3]])].map(f=>'family='+encodeURIComponent(f).replace(/%20/g,'+')).join('&');fonts.href='https://fonts.googleapis.com/css2?'+families+'&display=swap';render();if(persist){try{localStorage.setItem(KEY,JSON.stringify(i));$('appearance-storage').textContent='Saved on this device';}catch{$('appearance-storage').textContent='Applied for this visit; device storage is unavailable.';}}window.dispatchEvent(new CustomEvent('app-style-change',{detail:{index:i,name:t[0]}}));}
function like(){const removing=likes.includes(current);likes=removing?likes.filter(i=>i!==current):[...likes,current];let saved=true;try{localStorage.setItem(LIKES,JSON.stringify(likes));}catch{saved=false;}render();notice((removing?'Removed ':'♥ Liked ')+themes[current][0]+(saved?'':' · this visit only'));}
function showCurrentPage(){const index=visible().indexOf(current);if(index>=0)page=Math.floor(index/PAGE);}
function move(delta){const ids=visible();if(!ids.length)return;const index=ids.indexOf(current);const next=ids[index<0?0:(index+delta+ids.length)%ids.length];current=next;showCurrentPage();apply(next);}
function turn(delta){page+=delta;render();}
function showSection(name){for(const b of dialog.querySelectorAll('.settings-nav [data-settings-page]'))b.setAttribute('aria-current',b.dataset.settingsPage===name?'page':'false');for(const p of dialog.querySelectorAll('section[data-settings-page]'))p.hidden=p.dataset.settingsPage!==name;}
$('appearance-filters').innerHTML=categories.map(c=>`<button type="button" data-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('');
$('appearance-filters').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;page=0;render();}};
$('appearance-page-prev').onclick=()=>turn(-1);$('appearance-page-next').onclick=()=>turn(1);$('appearance-dots').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=Number(b.dataset.page);render();}};
dialog.querySelector('.settings-nav').addEventListener('click',e=>{const b=e.target.closest('[data-settings-page]');if(b)showSection(b.dataset.settingsPage);});
{let swipe=null;const grid=$('appearance-grid');grid.addEventListener('pointerdown',e=>{swipe={x:e.clientX,y:e.clientY};});grid.addEventListener('pointerup',e=>{if(!swipe)return;const dx=e.clientX-swipe.x,dy=e.clientY-swipe.y;swipe=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.5)turn(dx<0?1:-1);});}
$('appearance-grid').onclick=e=>{const b=e.target.closest('[data-style]');if(b)apply(Number(b.dataset.style));};
$('appearance-prev').onclick=()=>move(-1);$('appearance-next').onclick=()=>move(1);$('appearance-like').onclick=like;$('appearance-reset').onclick=()=>{category='All';current=7;showCurrentPage();apply(7);notice('Sunroom restored');};
toggle.onclick=()=>{showCurrentPage();render();dialog.showModal();toggle.setAttribute('aria-expanded','true');$('appearance-close').focus();};$('appearance-close').onclick=()=>dialog.close();dialog.onclose=()=>{toggle.setAttribute('aria-expanded','false');toggle.focus();};
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('keydown',e=>{if(!dialog.open||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();dialog.close();return;}if(e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key)||e.code==='Space'){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if(e.key==='ArrowLeft')move(-1);else if(e.key==='ArrowRight')move(1);else if(e.code==='Space'||e.key===' ')like();}},true);
window.addEventListener('storage',e=>{if(e.key===KEY){try{const i=JSON.parse(e.newValue);apply(Number.isInteger(i)&&i>=0&&i<themes.length?i:7,false);}catch{}}});
apply(current,false);toast.hidden=true;
}
